useEffect(() => {
  const id = setInterval(() => setTick(t => t + 1), 1000);
  return () => clearInterval(id);
}, []);

const inputRef = useRef(null);

useEffect(() => {
  inputRef.current?.focus();
}, []);

<input ref={inputRef} />

function useToggle(initial = false) {
  const [on, setOn] = useState(initial);
  const toggle = () => setOn(v => !v);
  return [on, toggle];
}
